from pathlib import Path
import numpy as np,pandas as pd
from NSCLC_native_MFA_math_v1 import sha


def main():
    root=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);source=root/'NSCLC_native_MFA_holdout_20261016_v2';proof=source/'private_independent_MFA_holdout_audit.json';accepted=json.loads(proof.read_text());assert accepted['status'].startswith('PASS_ALL60_') and accepted['producer_terminal_sha256']==sha(source/'private_terminal.json')
