    t=pd.read_csv(source/'private_all60_internal_holdout_coordination.tsv',sep='\t');assert len(t)==60 and t.slot.is_unique;stability=pd.read_csv(root/'NSCLC_native_MFA_discovery_20261016_v3/private_all20_discovery_only_factor_stability_matches.tsv',sep='\t').groupby('primary_factor').absolute_correlation.min();rows=[]
    for factor,g in t.groupby('factor'):
        assert len(g)==6;rows.append(dict(factor=factor,view_pairs=6,BH_supported=int((g.BH_q<.05).sum()),BY_supported=int((g.BY_q<.05).sum()),MC_upper_BH_supported=int((g.MC_upper_BH_q<.05).sum()),min_block_rho=float(g.block_rank_rho.min()),max_block_rho=float(g.block_rank_rho.max()),min_fixed_seed_discovery_rho=float(stability.loc[factor]),CI_excluding0_and_all_LOO_same_sign=int(((g.CI_low*g.CI_high>0)&g.LOO_same_sign&(g.LOO_valid==63)).sum()),independent_patient_or_direct_interaction_accepted=False))
    summary=pd.DataFrame(rows);out=root/'NSCLC_native_MFA_holdout_complete_review_20261016_v1';assert not out.exists();out.mkdir(mode=0o700);summary.to_csv(out/'private_all10_factor_coordination_summary.tsv',sep='\t',index=False);t.to_csv(out/'private_all60_original_audited_results.tsv',sep='\t',index=False)
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    factors=summary.factor.tolist();pairs=list(dict.fromkeys(zip(t.view_A,t.view_B)));matrix=np.array([[float(t[(t.factor==f)&(t.view_A==a)&(t.view_B==b)].block_rank_rho.iloc[0]) for a,b in pairs] for f in factors]);qs=np.array([[float(t[(t.factor==f)&(t.view_A==a)&(t.view_B==b)].BY_q.iloc[0]) for a,b in pairs] for f in factors]);labels=lambda s:s.replace('author_','').replace('_',' + ')
    fig,ax=plt.subplots(figsize=(12,7),constrained_layout=True);im=ax.imshow(matrix,aspect='auto',vmin=-1,vmax=1,cmap='coolwarm')
    for i in range(10):
        for j in range(6):ax.text(j,i,('%.2f'%matrix[i,j])+('*' if qs[i,j]<.05 else ''),ha='center',va='center',fontsize=11,color='white' if abs(matrix[i,j])>.65 else 'black')
    ax.set_xticks(range(6),[labels(a)+' / '+labels(b) for a,b in pairs],rotation=25,ha='right');ax.set_yticks(range(10),[x.rsplit('_',1)[-1] for x in factors]);ax.set_title('NSCLC native MFA: complete internal-holdout coordination\n63 author cases; own-view frozen projections; within histology x therapy blocks\n* complete60 BY<.05; RNA co-response does not prove direct communication',fontsize=11);fig.colorbar(im,ax=ax,label='Within-block rank correlation',shrink=.8);fig.savefig(out/'private_all60_holdout_coordination.png',dpi=150);plt.close(fig)
    counts=dict(slots=60,estimated=int(t.status.str.startswith('ESTIMATED_').sum()),BH=int((t.BH_q<.05).sum()),BY=int((t.BY_q<.05).sum()),MC_upper_BH=int((t.MC_upper_BH_q<.05).sum()))
    report='# Native four-view MFA: complete audited internal-holdout review\n\n'+json.dumps(counts,indent=2)+'\n\n'+summary.to_string(index=False)+'\n\nAll original60 slots retained. Gene filters, normalisation, technical regressions,10 factors, primary seed and conditional-rank block tests were fixed before learning or holdout testing. Each view score uses only its own RNA and frozen weights/noise. Training seeds measure numerical initialisation sensitivity, not independent biological replication.\n\nThe cohort has prior exploration. Author-case IDs have not become reviewed independent patients; within histology/therapy exchangeability remains an assumption. No clinical outcomes have been tested for these native factors. Shared stimulation, technical batch, demographic RNA and subtype composition can produce coordinated expression. No direct LR, resistant-state naming, old172/CM mapping or clinical prediction accepted. All learned genes and weights remain server-private.\n'
    (out/'PRIVATE_COMPLETE_NATIVE_MFA_HOLDOUT_REVIEW.md').write_text(report)
    question=dict(created_UTC=datetime.now(timezone.utc).isoformat(),basis_audit_sha256=sha(proof),scope='All10 primary factors x all4 views x all50 existing frozen Hallmark references; all40 view-factor and60 pair composition/technical diagnostics. No factor or function chosen by strongestP.',weight_annotation='Describe signed reference-vs-background weight contrasts and squared-weight fractions within the selected-feature universe, with coverage. Gene-set annotation of learned weights is not independent functional validation; no new P or FDR claim.',orthogonal_RNA='Before inspecting functional correlations, freeze a gene-disjoint complement excluding union of selected features of all four views from target AND background. Use existing complete per-cell-normalized native mean_logCP10K units pooled by actual cell counts. All50 references;>=20remaining targets,>=500background, report original-vs-remaining coverage and expression support. Train-only technical residual correction using the same frozen Q; heldout within-block correlations descriptive, no new P.',composition='All original author subtype fractions within each view, zeros preserved. Discovery-only fixed ridge alpha1 predicts every factor own-view score; heldout R2 and matched-case residual coordination for all60, no new P or selective covariate deletion.',technical_and_demographic='Complete score associations with existing source age/sex, histology/therapy and own quality; fixed small sex-linked/stress/lineage panels as diagnostics only. Do not label demographic, quality or mixture patterns as new interactions.',no_new_clinical_tests=True,original_author_annotations_or_CM_unchanged=True)
